const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const AI_MODEL = norm($env.AI_MODEL) || 'llama-3.3-70b-versatile';
const aiRequest = (system, user, temperature) => ({
  model: AI_MODEL, temperature: temperature === undefined ? 0.7 : temperature, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
});
const parseAi = (resp) => {
  const raw = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
  if (!raw) throw new Error('AI provider returned no content');
  let s = String(raw).trim();
  const m = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) s = m[1].trim();
  try { return JSON.parse(s); } catch (e) { throw new Error('AI provider returned invalid JSON: ' + e.message); }
};
const posts = (($input.first().json.data || {}).children || []).map((c) => c.data || {}).filter((d) => d.title);
if (!posts.length) return [];
const listing = posts.slice(0, 20).map((d, i) => (i + 1) + '. ' + norm(d.title).slice(0, 200) + ' :: ' + norm(d.selftext).slice(0, 300));
const system = 'You categorize community posts for Eki, a marketplace connecting African foodstuff vendors with buyers worldwide. Return ONLY JSON.';
const user = 'For each numbered post decide if it describes a pain point. Return JSON {"items":[{"index":1,"persona":"vendor|buyer","category":"DM_Chaos|Payment_Fraud|Scam_Fear|No_Buyers|Trust|Other","intensity":1-10,"keywords":["..."]}]}. Skip posts that are not pain points.\n\n' + listing.join('\n');
return [{ json: { ai_request: aiRequest(system, user, 0.2), posts: posts.slice(0, 20).map((d) => ({ title: norm(d.title), ups: d.ups || 0 })) } }];

